package ama.api;
import ama.contract.IdentityContracts.*;import ama.transcript.*;import ama.access.MeetingAccess;import ama.db.TransactionRunner;import jakarta.servlet.http.*;import java.io.*;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/meetings/{meetingId}/minutes") class MinutesController {
 private final MinutesConfiguration.Runtime runtime;private final JdbcMinutesSettingsReceipts settings;private final JdbcMinutesGenerationReceipts generations;private final TransactionRunner tx;private final MeetingAccess access;
 MinutesController(MinutesConfiguration.Runtime runtime,JdbcMinutesSettingsReceipts settings,JdbcMinutesGenerationReceipts generations,TransactionRunner tx,MeetingAccess access){this.runtime=runtime;this.settings=settings;this.generations=generations;this.tx=tx;this.access=access;}
 @GetMapping("/templates") ResponseEntity<byte[]> templates(@PathVariable String meetingId,@RequestParam(defaultValue="20") int limit,@RequestParam(required=false) String cursor,HttpServletRequest request)throws IOException{return json(200,queries(request,meetingId).templates(actor(request),meetingId,limit,cursor));}
 @PostMapping("/initial-settings") ResponseEntity<byte[]> initial(@PathVariable String meetingId,HttpServletRequest request)throws IOException{var body=MinutesWire.command(request,true);var actor=actor(request);String key=key(request);var replay=settings.lookup(actor,meetingId,key,body.expected(),body.template());if(replay.isPresent())return json(200,replay.orElseThrow());runtime.requireNewInitial();return json(200,runtime.initial().initialize(actor,meetingId,key,body.expected(),body.template(),UUID.randomUUID().toString()));}
 @PostMapping("/generations") ResponseEntity<byte[]> generate(@PathVariable String meetingId,HttpServletRequest request)throws IOException{var body=MinutesWire.command(request,false);var actor=actor(request);String key=key(request);var replay=generations.lookup(actor,meetingId,key,body.expected());if(replay.isPresent())return json(202,replay.orElseThrow());runtime.requireNewGeneration();return json(202,runtime.generation().enqueue(actor,meetingId,key,body.expected(),UUID.randomUUID().toString()));}
 @GetMapping("/generation-inputs/current") ResponseEntity<byte[]> current(@PathVariable String meetingId,HttpServletRequest request)throws IOException{return json(200,queries(request,meetingId).current(actor(request),meetingId));}
 @GetMapping("/generation-inputs/{inputId}") ResponseEntity<byte[]> input(@PathVariable String meetingId,@PathVariable String inputId,HttpServletRequest request)throws IOException{return json(200,queries(request,meetingId).input(actor(request),meetingId,inputId));}
 @GetMapping("/generation-tasks") ResponseEntity<byte[]> tasks(@PathVariable String meetingId,@RequestParam(defaultValue="20") int limit,@RequestParam(required=false) String cursor,HttpServletRequest request)throws IOException{return json(200,queries(request,meetingId).tasks(actor(request),meetingId,limit,cursor));}
 @GetMapping("/generation-tasks/{taskId}") ResponseEntity<byte[]> task(@PathVariable String meetingId,@PathVariable String taskId,HttpServletRequest request)throws IOException{return json(200,queries(request,meetingId).task(actor(request),meetingId,taskId));}
 @GetMapping("/candidates") ResponseEntity<byte[]> candidates(@PathVariable String meetingId,@RequestParam(defaultValue="20") int limit,@RequestParam(defaultValue="PENDING") String state,@RequestParam(required=false) String cursor,HttpServletRequest request)throws IOException{return json(200,queries(request,meetingId).candidates(actor(request),meetingId,limit,state,cursor));}
 @GetMapping("/candidates/{candidateId}") ResponseEntity<byte[]> candidate(@PathVariable String meetingId,@PathVariable String candidateId,HttpServletRequest request)throws IOException{return json(200,queries(request,meetingId).candidate(actor(request),meetingId,candidateId));}
 private JdbcMinutesQueries queries(HttpServletRequest request,String meeting){ama.contract.MinutesContracts.uuid(meeting);if(runtime.queries()!=null)return runtime.queries();tx.required(()->{access.require(access.lock(actor(request),meeting),MeetingAccess.Action.EDIT);return null;});throw new ama.contract.TranscriptContracts.Failure(503,"MINUTES_UNAVAILABLE");}
 private static String key(HttpServletRequest request){var values=Collections.list(request.getHeaders("Idempotency-Key"));if(values.size()!=1)throw new IllegalArgumentException("One idempotency key required");JdbcProcessingIntake.key(values.getFirst());return values.getFirst();}
 private static Actor actor(HttpServletRequest request){return ((ResolvedSession)request.getAttribute(SessionSecurityFilter.SESSION)).actor();}
 private static ResponseEntity<byte[]> json(int status,Object value)throws IOException{return ResponseEntity.status(status).contentType(MediaType.APPLICATION_JSON).header("Cache-Control","private, no-store").body(TranscriptWire.response(value,33554432));}
}
